public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int a = sc.nextInt();
    int[] t = new int[n];
    for (int i = 0; i < n; i++) {
        t[i] = sc.nextInt();
    }
    int current_time = 0;
    for (int i = 0; i < n; i++) {
        if (t[i] > current_time) {
            current_time = t[i] + a;
        } else {
            current_time += a;
        }
        System.out.println(current_time);
    }
}
